commands:
kubectl exec -n fleetcast deployment/fleetcast-satellite-app-backend -- python -c 'import urllib.request; r=urllib.request.urlopen("http://fleetcast-satellite-app-frontend/api/dashboard",timeout=10); print(r.status,r.headers.get("Content-Type"),r.read(100))'
cat > /tmp/fleetcast-nginx.yaml <<'EOF'
apiVersion: v1
kind: ConfigMap
metadata:
  name: fleetcast-frontend-nginx
  namespace: fleetcast
data:
  default.conf: |
    server {
      listen 80;
      server_name _;
      root /usr/share/nginx/html;
      index index.html;
      location /api/ {
        proxy_pass http://fleetcast-satellite-app-backend:5000;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
      }
      location ~* \.(js|css|json|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot)$ {
        try_files $uri $uri/ /index.html;
        access_log off;
        expires 1y;
        add_header Cache-Control "public";
      }
      location / {
        try_files $uri /index.html;
      }
    }
EOF
kubectl apply -f /tmp/fleetcast-nginx.yaml
kubectl patch deployment fleetcast-satellite-app-frontend -n fleetcast --type=strategic -p '{"spec":{"template":{"spec":{"volumes":[{"name":"nginx-config","configMap":{"name":"fleetcast-frontend-nginx"}}],"containers":[{"name":"frontend","volumeMounts":[{"name":"nginx-config","mountPath":"/etc/nginx/conf.d/default.conf","subPath":"default.conf","readOnly":true}]}]}}}}'
kubectl rollout status deployment/fleetcast-satellite-app-frontend -n fleetcast --timeout=90s
